parameters.jsCode:
// --------------------------------------------
// GET INPUT DATA
// --------------------------------------------

const estimateData =
  $('estimate_data').first().json.estimate_data;

const taskTypeInfo =
  $input.first().json.task_type_info || [];


// --------------------------------------------
// CREATE TASK TYPE MAP (USING CODE)
// --------------------------------------------

const taskTypeMap = {};

for (const item of taskTypeInfo) {

  const code = (item.task_type_code || '')
    .trim()
    .toUpperCase();

  if (!taskTypeMap[code]) {
    taskTypeMap[code] = [];
  }

  taskTypeMap[code].push(
    Number(item.task_type_ID)
  );
}


// --------------------------------------------
// TRACK USED IDS
// --------------------------------------------

const usedIndexes = {};


// --------------------------------------------
// MATCH TASK TYPE FUNCTION
// --------------------------------------------

function getTaskTypeId(taskCode) {

  const normalized = (taskCode || '')
    .trim()
    .toUpperCase();

  const possible = taskTypeMap[normalized];

  if (!possible || possible.length === 0) {
    return null;
  }

  if (!usedIndexes[normalized]) {
    usedIndexes[normalized] = 0;
  }

  const currentIndex = usedIndexes[normalized];

  const safeIndex =
    currentIndex >= possible.length
      ? possible.length - 1
      : currentIndex;

  usedIndexes[normalized]++;

  return possible[safeIndex];
}


// --------------------------------------------
// CHARGE TYPE ID FUNCTION
// --------------------------------------------

function getChargeTypeId(chargeType) {

  const normalized = (chargeType || '')
    .trim()
    .toLowerCase();

  if (normalized === 'time') {
    return 1;
  }

  if (normalized === 'supplier') {
    return 3;
  }

  return null;
}


// --------------------------------------------
// CREATE ENTRIES
// --------------------------------------------

const entries = estimateData.map((row) => {

  // USING TASK TYPE CODE NOW
  const taskCode =
    row["Task Type Code"] ||
    row["TaskTypeCode"] ||
    row["task_type_code"] ||
    "";

  return {

    taskTypeId: getTaskTypeId(taskCode),

    description:
      row["Description"] || "",

    chargeTypeId:
      getChargeTypeId(row["Charge Type"]),

    units:
      Number(row["Units"] || 0),

    rate:
      Number(row["Rate"] || 0),

    markUp:
      Number(row["Mark Ups"] || 0),

    notes:
      row["Estimate Notes"]

  };

});


// --------------------------------------------
// REMOVE INVALID ENTRIES
// --------------------------------------------

const validEntries = entries.filter(
  e => e.taskTypeId !== null
);


// --------------------------------------------
// RETURN VALID N8N OBJECT
// --------------------------------------------

return [
  {
    json: {
      entries: validEntries
    }
  }
];

